    ]
  },
  "hypotheses": [
    {
      "name": "안정형 협심증 / 만성 관상동맥 질환(운동 유발 협심증)",
      "icd10": "I20.8",
      "must_not_miss": false,
      "probability_band": "high",
      "supports": [
        { "text": "계단 오를 때(운동) 압박성 흉부 증상, 휴식 시 호전 — 전형적 운동 유발·휴식 완화 패턴", "basis": "history" },
        { "text": "고혈압·당뇨 병력 = 주요 관상동맥 위험 인자 2개", "basis": "history" },
        { "text": "혈압 148/92(환자 제공값)", "basis": "measurement" }
      ],
      "against": [
        { "text": "증상 지속 시간·방사통·식은땀 동반 여부 미확인 — 전형성 등급을 확정할 수 없음", "basis": "history" }
