      "probability_band": "medium",
      "supports": [
        { "text": "3주째 지속되는 운동 유발 흉통 — 최근 시작·진행 양상이면 불안정 패턴 가능(발병 시점·빈도 변화 미확인)", "basis": "history" }
      ],
      "against": [
        { "text": "휴식 시 호전, 현재 안정 — 안정 시 지속/악화 패턴은 확인되지 않음", "basis": "history" },
        { "text": "심전도·심근 표지자 없음", "basis": "measurement" }
      ]
    },
    {
      "name": "대동맥 박리",
      "icd10": "I71.0",
      "must_not_miss": true,
      "probability_band": "low",
