      ],
      "against": [
        { "text": "운동 유발·휴식 완화 패턴은 협심증 쪽에 더 부합", "basis": "history" }
      ]
    },
    {
      "name": "대동맥 판막 협착 등 판막 질환(운동 시 증상)",
      "icd10": "I35.0",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "고령 남성 — 판막 질환 유병 가능성", "basis": "history" }
      ],
      "against": [
