      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "운동과의 명확한 인과 미확인", "basis": "history" }
      ],
      "against": [
        { "text": "운동 유발-휴식 완화 패턴과 위험 인자 2개는 심장 기원에 부합. 심장 질환 배제 근거 없이는 우선 배제 불가", "basis": "guideline" }
      ]
    }
  ],
  "missing_info": [
    "같은 강도의 활동에서 유발되는 증상이 3주 전 처음 시작된 것인지, 아니면 최근 더 쉽게·더 자주·더 오래 지속되는지(안정형 vs 불안정 협심증 감별에 가장 판별력이 큼)"
  ],
  "suggested_tests": [
    { "name": "12유도 심전도(현재, 가능하면 증상 시)", "purpose": "급성 관동맥 증후군 배제, 기존 허혈·부정맥 확인", "urgency": "now", "basis": "guideline" },
    { "name": "심근 표지자(트로포닌)", "purpose": "급성 관동맥 증후군 배제", "urgency": "now", "basis": "guideline" },
    { "name": "경흉부 심초음파", "purpose": "좌심실 기능·벽운동 이상·판막 질환·구조적 원인 평가(검사 우선순위상 운동부하·CT에 앞서 기저 심기능 확보)", "urgency": "24h", "basis": "guideline" },
    { "name": "운동부하 검사(운동 가능·심전도 해석 가능 시)", "purpose": "유발 허혈 확인 및 기능적 등급화", "urgency": "24h", "basis": "guideline" },
    { "name": "관상동맥 CT 혈관조영(운동 불가·심전도 비진단적·사전확률 중간군 등 기관 기준에 해당 시 대안)", "purpose": "관상동맥 협착 해부학적 평가", "urgency": "24h", "basis": "guideline" },
    { "name": "관상동맥 조영술", "purpose": "고위험 소견·증상 악화·비침습 검사 고위험일 때 확정 진단·중재 목적", "urgency": "routine", "basis": "guideline" },
    { "name": "기본 혈액검사(지질·HbA1c·신기능·전해질·혈색소)", "purpose": "위험 인자·동반 질환·치료 기반 평가", "urgency": "routine", "basis": "guideline" }
  ],
  "suggested_treatments": [
