[CONSULT_SPECIALIST 결과 — 내분비대사내과]
[K-Doctor 전문과목 내분비대사내과 v0.1 적용]

[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-endocrinology",
  "answer": "당뇨 조절 지표는 (a) 환자가 직접 준 최근 당화 혈색소(HbA1c)와 측정일, (b) CGM 지표(측정 기간, 목표 범위 내 시간 TIR, 저혈당 시간 TBR, 평균 혈당, 변동 계수)를 인용하는 방식으로만 확인해야 하며, 이 SP는 진단 기준·목표 수치를 제시하지 않는다. 당뇨병성 자율신경병증은 안정 시 빈맥, 기립성 저혈압, 운동 내성 저하, 무증상 심근경색·비전형 흉통을 만들 수 있어, 흉통 평가에서 '당뇨이니까 본태성' 혹은 '당뇨이니까 비심장성'으로 어느 쪽으로도 성급히 정리하면 안 된다.",
  "red_flag": {
    "present": false,
    "items": [
      { "id": "R_cardiac_chest_pain", "evidence": "62세 남성, 흉통 평가 중 — 원인 미확정", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "당뇨 조절 상태 미상 — HbA1c/CGM 데이터 결손 (수치 자체가 위험 인자)",
      "icd10": "E11.9",
      "must_not_miss": false,
      "probability_band": "high",
      "supports": [
        { "text": "당뇨 병력 있으나 조절 상태 미상 — 심혈관 위험 평가에 결정적 변수", "basis": "history" },
        { "text": "62세 남성 = 관상동맥질환 호발 연령·성별", "basis": "history" }
      ],
      "against": [
        { "text": "HbA1c·CGM 값이 입력에 없음", "basis": "measurement" }
      ]
    },
    {
      "name": "당뇨병성 심혈관 자율신경병증(무증상 심근허혈·비전형 흉통)",
      "icd10": "E11.43",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "당뇨병에서 자율신경병증은 무증상 심근경색·비전형 흉통과 연관(일반 내분비 교과 지식)", "basis": "guideline" },
        { "text": "안정 시 빈맥, 기립성 저혈압, 운동 시 혈압 반응 둔화가 시사 소견", "basis": "history" }
      ],
      "against": [
        { "text": "안정 시 심박수·기립 시 혈압 변화·운동 부하 반응 데이터가 입력에 없음", "basis": "measurement" },
        { "text": "당뇨 유병 기간·기존 망막·신장·신경 합병증 병력 미상", "basis": "history" }
      ]
    },
    {
      "name": "급성 관상동맥 증후군 (당뇨에서 비전형 양상으로 나타날 수 있음)",
      "icd10": "I24.9",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "62세 남성 + 당뇨 = 고위험 프로필", "basis": "history" }
      ],
      "against": [
        { "text": "심전도·트로포닌·증상 양상(압박성, 방사, 발한, 호흡곤란) 미상", "basis": "measurement" }
      ]
    }
  ],
  "missing_info": [
    "흉통 발생 시각과 현재 시각, 그리고 흉통 양상(압박성·지속시간·방사·발한·호흡곤란 동반) — 그리고 가능하면 최근 HbA1c 값과 측정일"
  ],
  "suggested_tests": [
    { "name": "HbA1c (환자가 준 최근 값 우선 확인, 없으면 시행)", "purpose": "지난 2~3개월 평균 혈당 조절 상태 파악", "urgency": "24h", "basis": "guideline" },
    { "name": "CGM 지표 확인(측정 중이면 리포트): TIR/TBR/평균 혈당/변동 계수", "purpose": "혈당 변동·저혈당 노출 평가 — 저혈당은 흉통 감별의 혼란 요인", "urgency": "24h", "basis": "guideline" },
    { "name": "기립 시 혈압·심박수 측정(누운 자세 → 기립 1·3분)", "purpose": "심혈관 자율신경병증 시사 소견 확인", "urgency": "routine", "basis": "guideline" },
    { "name": "당뇨 합병증 스크리닝 병력 확인(망막증·신장병증·말초신경병증)", "purpose": "자율신경병증 선행 위험도 추정", "urgency": "routine", "basis": "history" }
  ],
  "suggested_treatments": [
    { "kind": "referral", "description": "흉통 평가는 kdoctor-cardiology 주도로 진행. 본 SP는 당뇨 조절 데이터·자율신경병증 시사 소견만 제공.", "basis": "consult" }
  ],
  "handoff": {
    "better_specialty": "kdoctor-cardiology",
    "reason": "흉통 원인 확정·심전도·트로포닌·관상동맥 평가는 순환기 영역. 본 SP는 당뇨 조절 지표·자율신경병증 시사점 보조 역할."
  },
  "confidence": { "clinical": 3, "information": 1 },
  "warnings": [
    "[내분비 규칙 1] HbA1c·CGM 수치 목표·정상 범위는 이 SP가 제시하지 않는다 — 환자·기관 판정을 인용하거나 '기관 기준 확인'으로 둔다.",
    "[내분비 규칙 4] 당뇨약·인슐린 조절 관련 어떤 변경도 이 답변에 포함되지 않으며, 흉통 평가 중 임의 조절은 금지 안내 대상이다.",
    "[내분비 규칙 2] 흉통 자체는 R계 위험 신호로, 당뇨 조절 지표 회신보다 응급 평가가 먼저다. 흉통이 지속·악화되면 즉시 응급 평가.",
    "[규칙 C6] 62세 = 노인 기준 해당. 저혈당·기립성 저혈압·다약제 상호작용 확인 후 처치 소견.",
    "본 소견은 전문의 검토 전 초안 규칙 기반이며 실행 검증되지 않았다."
  ]
}
[/SPECIALIST_FINDING]

자기 점검: C1(적용, RED_FLAG 미해당 — 흉통은 카디올로지 핸드오프)·C2(모든 항목 basis 부착)·C3(확정 표현 없음)·C4(용량 서술 없음) 위반 없음.

